CREATE VIEW "v_actividad_hoja" AS select "a"."id" AS "id","a"."proyecto_id" AS "proyecto_id","a"."fase_id" AS "fase_id","a"."padre_id" AS "padre_id","a"."nombre" AS "nombre","a"."descripcion" AS "descripcion","a"."responsable_id" AS "responsable_id","a"."estado_codigo" AS "estado_codigo","a"."prioridad" AS "prioridad","a"."fecha_inicio" AS "fecha_inicio","a"."fecha_fin" AS "fecha_fin","a"."horas_estimadas" AS "horas_estimadas","a"."avance" AS "avance","a"."peso" AS "peso","a"."motivo_cambio" AS "motivo_cambio","a"."archivada" AS "archivada","a"."creado_en" AS "creado_en","a"."actualizado_en" AS "actualizado_en" from (("actividad" "a" join "proyecto" "p" on((("p"."id" = "a"."proyecto_id") and ("p"."archivado" = 0)))) join "fase" "f" on((("f"."id" = "a"."fase_id") and ("f"."archivada" = 0)))) where (("a"."archivada" = 0) and exists(select 1 from "actividad" "h" where ("h"."padre_id" = "a"."id")) is false)
